"""${{ values.name }} — generated by the agent blueprint v2.0.0."""
import os

from platform_sdk import Context, Gateway

ALIAS = os.environ.get("SERVICE_ALIAS", "${{ values.alias }}")
gateway = Gateway(ctx=Context(tenant="${{ values.tenant }}", feature="agent"))


from platform_agents import TaskBudget  # agents/platform_agents (Chapter 12)

TOOLS = ["orders.lookup"]          # from the tool registry; approvals enforced there


def handle(task: str, budget: TaskBudget):
    budget.charge_step()
    return gateway.chat([{"role": "user", "content": task}], alias=ALIAS).text


def eval_answer(question: str):
    return handle(question, TaskBudget(max_steps=8, max_usd=0.50)), []
